  /// < miniaudio_player_silence_mode_t
  @ffi.Int32()
  external int mode;

  /// < Silence threshold in dBFS (default: -45.0f, range: -90.0 to -10.0)
  @ffi.Float()
  external double threshold_db;

  /// < Minimum silence duration before skipping (default: 300ms)
  @ffi.Uint32()
  external int min_silence_duration_ms;

  /// < Safety margin before and after voice (default: 50ms)
  @ffi.Uint32()
  external int padding_ms;

  static ffi.Pointer<miniaudio_player_silence_config_t> $allocate(
    ffi.Allocator $allocator, {
    required int mode,
    required double threshold_db,
    required int min_silence_duration_ms,
    required int padding_ms,
  }) =>
      $allocator<miniaudio_player_silence_config_t>()
        ..ref.mode = mode
        ..ref.threshold_db = threshold_db
        ..ref.min_silence_duration_ms = min_silence_duration_ms
        ..ref.padding_ms = padding_ms;
}

/// ========================================================================= */
/// /* Silence Detection & Skipping Parameters                                   */
/// /* =========================================================================
enum miniaudio_player_silence_mode_t {
  MAP_SILENCE_MODE_DISABLED(0),
  MAP_SILENCE_MODE_TRIM_EDGES(1),
  MAP_SILENCE_MODE_CONTINUOUS(2),
  MAP_SILENCE_MODE_ALL(3);

  final int value;
  const miniaudio_player_silence_mode_t(this.value);

  static miniaudio_player_silence_mode_t fromValue(int value) =>
      switch (value) {
        0 => MAP_SILENCE_MODE_DISABLED,
        1 => MAP_SILENCE_MODE_TRIM_EDGES,
        2 => MAP_SILENCE_MODE_CONTINUOUS,
        3 => MAP_SILENCE_MODE_ALL,
        _ => throw ArgumentError(
            'Unknown value for miniaudio_player_silence_mode_t: $value'),
      };
}

final class miniaudio_player_status_t extends ffi.Struct {
  /// < Current position in milliseconds
  @ffi.Int64()
  external int position_ms;

  /// < Total duration in milliseconds
  @ffi.Int64()
  external int duration_ms;

  /// < 1 if actively playing, 0 if paused/stopped
  @ffi.Int32()
  external int is_playing;

  /// < 1 if buffering, 0 otherwise
  @ffi.Int32()
  external int is_buffering;

  /// < 1 if track completed, 0 otherwise
  @ffi.Int32()
  external int is_completed;

  /// < miniaudio_player_playback_state_t
  @ffi.Int32()
  external int state;

  /// < Current volume (0.0 to 1.0+)
  @ffi.Float()
  external double volume;

  /// < Playback speed multiplier (0.1 to 4.0+)
  @ffi.Float()
  external double rate;

  /// < Pitch multiplier (0.1 to 4.0+)
  @ffi.Float()
  external double pitch;

  /// < Audio bitrate in bits per second (bps)
  @ffi.Uint32()
  external int bitrate;

  /// < Current 10-band equalizer settings
  external miniaudio_player_equalizer_params_t equalizer;

  /// < Currently active audio output device
  external miniaudio_device_info_t device;

  /// < Currently active silence skipping settings
  external miniaudio_player_silence_config_t silence;

  /// < Cumulative duration of skipped silence in ms
  @ffi.Int64()
  external int silence_saved_ms;

  /// < 1 if real-time visualizer enabled, 0 otherwise
  @ffi.Int32()
  external int visualizer_enabled;

  /// < Real-time 10-band visualizer data
  external miniaudio_player_visualizer_data_t visualizer;
}

/// Opaque player handle
typedef miniaudio_player_t = ffi.Opaque;

final class miniaudio_player_visualizer_data_t extends ffi.Struct {
  /// < 10 normalized frequency bands (0.0 to 1.0) matching EQ bands
  @ffi.Array.multi([10])
  external ffi.Array<ffi.Float> bands;

  /// < Global RMS energy (0.0 to 1.0)
  @ffi.Float()
  external double rms;

  /// < Peak amplitude (0.0 to 1.0)
  @ffi.Float()
  external double peak;

  /// < Left channel level (0.0 to 1.0)
  @ffi.Float()
  external double left;

  /// < Right channel level (0.0 to 1.0)
  @ffi.Float()
  external double right;
}

final class miniaudio_replay_gain_data_t extends ffi.Struct {
  /// < Recommended ReplayGain in dB relative to target LUFS
  @ffi.Float()
  external double gain_db;

  /// < Peak sample value (1.0 = 0 dBFS)
  @ffi.Float()
  external double peak;

  /// < Integrated perceived loudness in LUFS
  @ffi.Float()
  external double lufs;

  static ffi.Pointer<miniaudio_replay_gain_data_t> $allocate(
    ffi.Allocator $allocator, {
    required double gain_db,
    required double peak,
    required double lufs,
  }) =>
      $allocator<miniaudio_replay_gain_data_t>()
        ..ref.gain_db = gain_db
        ..ref.peak = peak
        ..ref.lufs = lufs;
}

final class miniaudio_waveform_data_t extends ffi.Struct {
  /// < Number of points in the array
  @ffi.Uint32()
  external int point_count;

  /// < Dynamically allocated array of normalized points (0.0 to 1.0)
  external ffi.Pointer<ffi.Float> points;

  static ffi.Pointer<miniaudio_waveform_data_t> $allocate(
    ffi.Allocator $allocator, {
    required int point_count,
    required ffi.Pointer<ffi.Float> points,
  }) =>
      $allocator<miniaudio_waveform_data_t>()
        ..ref.point_count = point_count
        ..ref.points = points;
}
